@push('scripts')
<script>
(() => {
const initial=@json($initialBlocks),list=document.getElementById('npb-sections'),empty=document.getElementById('npb-empty'),hidden=document.getElementById('builder-blocks'),title=document.getElementById('npb-title'),excerpt=document.getElementById('npb-excerpt');if(!list)return;
const catalog={hero:['Hero','fa-solid fa-rocket'],rich_text:['Rich Text','fa-solid fa-align-left'],image:['Image','fa-regular fa-image'],split:['Image + Content','fa-solid fa-table-columns'],cards:['Cards','fa-solid fa-grip'],stats:['Stats','fa-solid fa-chart-simple'],cta:['Call to Action','fa-solid fa-bullhorn'],video:['Video','fa-solid fa-circle-play'],divider:['Divider','fa-solid fa-minus']};
const defaults={hero:{eyebrow:'FEATURED',title:'',content:'',image:'',image_alt:'',button_text:'',button_url:'',tone:'dark',align:'left',visible:true},rich_text:{eyebrow:'',title:'',content:'',tone:'dark',align:'left',visible:true},image:{eyebrow:'',title:'',content:'',image:'',image_alt:'',tone:'dark',align:'left',visible:true},split:{eyebrow:'',title:'',content:'',image:'',image_alt:'',button_text:'',button_url:'',layout:'image-left',tone:'dark',align:'left',visible:true},cards:{eyebrow:'',title:'',content:'',columns:3,tone:'dark',items:[{title:'Feature title',content:'Feature description.'},{title:'Another feature',content:'Supporting description.'},{title:'Third feature',content:'Supporting description.'}],visible:true},stats:{eyebrow:'',title:'',content:'',tone:'accent',items:[{value:'100%',label:'Clean output'},{value:'24/7',label:'Availability'},{value:'0',label:'Fuel required'},{value:'∞',label:'Scalable'}],visible:true},cta:{eyebrow:'NEXT STEP',title:'Ready to explore?',content:'Connect with our team to learn more.',button_text:'Get in touch',button_url:'/contact',tone:'accent',align:'center',visible:true},video:{title:'',content:'',url:'',tone:'dark',visible:true},divider:{tone:'dark',visible:true}};
const clone=o=>JSON.parse(JSON.stringify(o)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),url=v=>/^(javascript|data|vbscript):/i.test(String(v??'').trim())?'#':String(v??'').trim()||'#';
let blocks=Array.isArray(initial)?initial.map(normalize):[];let dragged=null;
function normalize(b){const type=catalog[b?.type]?b.type:'rich_text',x=Object.assign(clone(defaults[type]),b||{},{type});if(Array.isArray(defaults[type].items))x.items=Array.isArray(b?.items)&&b.items.length?b.items.map(i=>Object.assign({},defaults[type].items[0],i||{})):clone(defaults[type].items);return x}
function input(label,key,value,kind='text',item=false){const a=item?'data-item-field':'data-field';return `<div class="npb-field"><label>${esc(label)}</label>${kind==='textarea'?`<textarea ${a}="${key}" rows="4">${esc(value)}</textarea>`:`<input ${a}="${key}" type="${kind}" value="${esc(value)}">`}</div>`}
function select(label,key,value,opts){return `<div class="npb-field"><label>${esc(label)}</label><select data-field="${key}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`}
function common(b){return `<div class="npb-grid">${input('Eyebrow','eyebrow',b.eyebrow||'')}${input('Section title','title',b.title||'')}${select('Tone','tone',b.tone||'dark',[['dark','Dark'],['accent','Accent'],['light','Soft']])}${select('Alignment','align',b.align||'left',[['left','Left'],['center','Center'],['right','Right']])}</div>`}
function items(b){return `<div class="npb-field full"><label>Items</label><div class="npb-items">${(b.items||[]).map((i,j)=>`<div class="npb-item" data-item="${j}"><div class="npb-item-grid">${input('Title','title',i.title||'','text',true)}${input('Description','content',i.content||'','textarea',true)}${b.type==='stats'?input('Value','value',i.value||'','text',true)+input('Label','label',i.label||'','text',true):''}</div><button type="button" class="npb-item-remove" data-remove-item="${j}"><i class="fa-solid fa-xmark"></i></button></div>`).join('')}</div><button type="button" class="npb-add-item" data-add-item><i class="fa-solid fa-plus"></i> Add item</button></div>`}
function body(b){if(b.type==='divider')return `<label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label>`;if(b.type==='rich_text')return `${common(b)}<div class="npb-grid"><div class="npb-field full"><label>Content</label><textarea data-field="content" rows="8">${esc(b.content||'')}</textarea></div><label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label></div>`;if(b.type==='hero')return `${common(b)}<div class="npb-grid">${input('Image URL','image',b.image||'','url')}${input('Image alt text','image_alt',b.image_alt||'')}${input('Button text','button_text',b.button_text||'')}${input('Button URL','button_url',b.button_url||'','url')}<div class="npb-field full"><label>Content</label><textarea data-field="content" rows="5">${esc(b.content||'')}</textarea></div><label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label></div>`;if(b.type==='image')return `${common(b)}<div class="npb-grid">${input('Image URL','image',b.image||'','url')}${input('Alt text','image_alt',b.image_alt||'')}<div class="npb-field full"><label>Caption</label><textarea data-field="content" rows="4">${esc(b.content||'')}</textarea></div><label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label></div>`;if(b.type==='split')return `${common(b)}<div class="npb-grid">${input('Image URL','image',b.image||'','url')}${input('Alt text','image_alt',b.image_alt||'')}${select('Image position','layout',b.layout||'image-left',[['image-left','Image left'],['image-right','Image right']])}${input('Button text','button_text',b.button_text||'')}<div class="npb-field full"><label>Content</label><textarea data-field="content" rows="5">${esc(b.content||'')}</textarea></div>${input('Button URL','button_url',b.button_url||'','url')}<label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label></div>`;if(b.type==='cards')return `${common(b)}<div class="npb-grid">${select('Columns','columns',b.columns||3,[['2','2 columns'],['3','3 columns'],['4','4 columns']])}</div>${items(b)}<label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label>`;if(b.type==='stats')return `${common(b)}${items(b)}<label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label>`;if(b.type==='cta')return `${common(b)}<div class="npb-grid">${input('Button text','button_text',b.button_text||'')}${input('Button URL','button_url',b.button_url||'','url')}<div class="npb-field full"><label>Content</label><textarea data-field="content" rows="4">${esc(b.content||'')}</textarea></div><label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label></div>`;if(b.type==='video')return `${common(b)}<div class="npb-grid">${input('Video URL','url',b.url||'','url')}<div class="npb-field full"><label>Context</label><textarea data-field="content" rows="4">${esc(b.content||'')}</textarea></div><label class="npb-check"><input data-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Show section</label></div>`;return ''}
function render(){list.innerHTML='';empty.style.display=blocks.length?'none':'grid';blocks.forEach((b,i)=>{const [label,icon]=catalog[b.type],el=document.createElement('article');el.className='npb-section open';el.draggable=true;el.dataset.index=i;el.dataset.type=b.type;el.innerHTML=`<header class="npb-sec-head"><span class="npb-grip"><i class="fa-solid fa-grip-vertical"></i></span><div class="npb-sec-name"><strong>${esc(label)}</strong><small>${b.visible===false?'Hidden':'Visible'} · Drag to reorder</small></div><div class="npb-sec-tools"><button type="button" class="npb-tool" data-dup title="Duplicate"><i class="fa-regular fa-copy"></i></button><button type="button" class="npb-tool" data-open title="Collapse"><i class="fa-solid fa-chevron-up"></i></button><button type="button" class="npb-tool danger" data-del title="Delete"><i class="fa-regular fa-trash-can"></i></button></div></header><div class="npb-body">${body(b)}</div>`;el.querySelector('[data-open]').onclick=()=>{el.classList.toggle('open');el.querySelector('[data-open] i').className=el.classList.contains('open')?'fa-solid fa-chevron-up':'fa-solid fa-chevron-down'};el.querySelector('[data-del]').onclick=()=>{blocks.splice(i,1);commit()};el.querySelector('[data-dup]').onclick=()=>{blocks.splice(i+1,0,clone(b));commit()};el.querySelectorAll('[data-field]').forEach(c=>c.addEventListener(c.type==='checkbox'?'change':'input',()=>{b[c.dataset.field]=c.type==='checkbox'?c.checked:c.value;commit(false)}));el.querySelectorAll('[data-item-field]').forEach(c=>c.addEventListener('input',()=>{const item=b.items?.[Number(c.closest('[data-item]').dataset.item)];if(item)item[c.dataset.itemField]=c.value;commit(false)}));el.querySelector('[data-add-item]')?.addEventListener('click',()=>{b.items=b.items||[];b.items.push(b.type==='stats'?{value:'',label:'Metric'}:{title:'New item',content:'Description'});commit()});el.querySelectorAll('[data-remove-item]').forEach(btn=>btn.addEventListener('click',()=>{b.items.splice(Number(btn.dataset.removeItem),1);commit() }));el.addEventListener('dragstart',()=>{dragged=i;el.classList.add('dragging')});el.addEventListener('dragend',()=>{dragged=null;el.classList.remove('dragging')});el.addEventListener('dragover',e=>e.preventDefault());el.addEventListener('drop',e=>{e.preventDefault();if(dragged===null||dragged===i)return;const x=blocks.splice(dragged,1)[0];blocks.splice(i,0,x);dragged=null;commit()});list.appendChild(el)});commit(false)}
function preview(b){if(b.visible===false)return '';const title=b.title?`<h3>${esc(b.title)}</h3>`:'';const copy=b.content?`<div class="npb-preview-copy">${String(b.content).replace(/<script[\s\S]*?<\/script>/gi,'').slice(0,8000)}</div>`:'';const kicker=b.eyebrow?`<div class="npb-preview-kicker">${esc(b.eyebrow)}</div>`:'';if(b.type==='divider')return '<div class="npb-preview-divider"></div>';if(b.type==='hero')return `<section class="npb-preview-sec"><div class="npb-preview-hero"><div class="npb-preview-inner">${kicker}${title}${copy}${b.button_text?`<a class="npb-preview-btn" href="${esc(url(b.button_url))}">${esc(b.button_text)}</a>`:''}</div><div class="npb-preview-media">${b.image?`<img src="${esc(url(b.image))}" alt="${esc(b.image_alt||b.title||'')}">`:'<i class="fa-regular fa-image"></i>'}</div></div></section>`;if(b.type==='rich_text')return `<section class="npb-preview-sec"><div class="npb-preview-inner">${kicker}${title}${copy||'<p>Rich content will appear here.</p>'}</div></section>`;if(b.type==='image')return `<section class="npb-preview-sec">${b.image?`<img class="npb-preview-image" src="${esc(url(b.image))}" alt="${esc(b.image_alt||b.title||'')}">`:'<div class="npb-preview-media"><i class="fa-regular fa-image"></i></div>'}${title||copy?`<div class="npb-preview-inner">${title}${copy}</div>`:''}</section>`;if(b.type==='split'){const m=`<div class="npb-preview-media">${b.image?`<img src="${esc(url(b.image))}" alt="${esc(b.image_alt||'')}">`:'<i class="fa-regular fa-image"></i>'}</div>`,c=`<div class="npb-preview-inner">${kicker}${title}${copy}</div>`;return `<section class="npb-preview-sec"><div class="npb-preview-split">${b.layout==='image-right'?c+m:m+c}</div></section>`}if(b.type==='cards')return `<section class="npb-preview-sec"><div class="npb-preview-inner">${kicker}${title}${copy}</div><div class="npb-preview-cards c${Math.min(4,Math.max(2,Number(b.columns)||3))}">${(b.items||[]).map(x=>`<div class="npb-preview-card"><strong>${esc(x.title||'Card')}</strong><span>${esc(x.content||'')}</span></div>`).join('')}</div></section>`;if(b.type==='stats')return `<section class="npb-preview-sec"><div class="npb-preview-inner">${kicker}${title}${copy}</div><div class="npb-preview-stats">${(b.items||[]).map(x=>`<div class="npb-preview-stat"><strong>${esc(x.value||'—')}</strong><span>${esc(x.label||'')}</span></div>`).join('')}</div></section>`;if(b.type==='cta')return `<section class="npb-preview-sec"><div class="npb-preview-cta">${kicker}${title}${copy}<a class="npb-preview-btn" href="${esc(url(b.button_url))}">${esc(b.button_text||'Learn more')}</a></div></section>`;if(b.type==='video')return `<section class="npb-preview-sec"><div class="npb-preview-video"><i class="fa-solid fa-circle-play"></i><span>${esc(b.url||'Add a video URL')}</span></div></section>`;return ''}
function commit(redraw=true){hidden.value=JSON.stringify(blocks);if(redraw)render();document.getElementById('npb-preview').innerHTML=`<section class="npb-preview-sec"><div class="npb-preview-inner"><div class="npb-preview-kicker">PAGE</div><h3>${esc(title?.value||'Untitled page')}</h3>${excerpt?.value?`<p>${esc(excerpt.value)}</p>`:''}</div></section>${blocks.map(preview).join('')}`}
function add(type){blocks.push(normalize({type}));commit();setTimeout(()=>list.lastElementChild?.scrollIntoView({behavior:'smooth',block:'center'}),20)}
document.getElementById('npb-add')?.addEventListener('click',e=>{const old=document.querySelector('.npb-chooser');if(old){old.remove();return}const box=document.createElement('div');box.className='npb-chooser';box.innerHTML=Object.entries(catalog).map(([k,v])=>`<button type="button" data-t="${k}"><i class="${v[1]}"></i><span>${esc(v[0])}</span></button>`).join('');document.querySelector('.npb-builder-head').appendChild(box);box.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{add(b.dataset.t);box.remove()})});title?.addEventListener('input',()=>commit(false));excerpt?.addEventListener('input',()=>commit(false));commit();
})();
</script>
<style>.npb-builder-head{position:relative}.npb-chooser{position:absolute;right:12px;top:58px;width:min(360px,calc(100% - 24px));display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:8px;background:#061720;border:1px solid rgba(103,208,234,.2);border-radius:11px;box-shadow:0 18px 40px rgba(0,0,0,.4);z-index:50}.npb-chooser button{display:flex;align-items:center;gap:7px;border:1px solid rgba(103,208,234,.08);border-radius:8px;background:rgba(255,255,255,.02);color:#cde7ec;padding:8px;text-align:left;cursor:pointer;font-size:8px}.npb-chooser button:hover{background:rgba(73,213,239,.06);border-color:rgba(73,213,239,.25)}.npb-chooser i{width:22px;height:22px;display:grid;place-items:center;border-radius:6px;background:rgba(73,213,239,.08);color:#54d7ed}@media(max-width:520px){.npb-chooser{grid-template-columns:1fr;right:7px;top:100px}}</style>
@endpush
